<?php
/** АвтоСпа theme functions. */
if (!defined('ABSPATH')) { exit; }
function avtospa_setup(){add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('html5',array('search-form','comment-form','comment-list','gallery','caption','style','script'));register_nav_menus(array('primary'=>'Основное меню','footer'=>'Меню в подвале'));} add_action('after_setup_theme','avtospa_setup');
function avtospa_assets(){
 $version=wp_get_theme()->get('Version');
 wp_enqueue_style('avtospa-style',get_stylesheet_uri(),array(),$version);
 foreach(array('tire-booking','header-premium','hero-premium','services-premium','feature-sections','location-contacts-premium','benefits-faq-footer','service-page') as $css){wp_enqueue_style('avtospa-'.$css,get_template_directory_uri().'/assets/css/'.$css.'.css',array('avtospa-style'),$version);}
 wp_enqueue_style('avtospa-palette-refresh',get_template_directory_uri().'/assets/css/palette-refresh.css',array('avtospa-style','avtospa-tire-booking','avtospa-header-premium','avtospa-hero-premium','avtospa-services-premium','avtospa-feature-sections','avtospa-location-contacts-premium','avtospa-benefits-faq-footer','avtospa-service-page'),$version);
 wp_enqueue_script('avtospa-navigation',get_template_directory_uri().'/assets/js/navigation.js',array(),$version,true);wp_script_add_data('avtospa-navigation','strategy','defer');
 $interactive_css=':root{--avtospa-glow:rgba(34,159,208,.16)}.avtospa-progress{position:fixed;left:0;top:0;height:4px;width:0;background:linear-gradient(90deg,#229fd0,#58b9e8,#ff9b52,#f39acb);z-index:9999;pointer-events:none;border-radius:0 99px 99px 0}.avtospa-reveal{opacity:0;transform:translateY(22px);transition:opacity .65s ease,transform .65s ease}.avtospa-reveal.is-visible{opacity:1;transform:none}.avtospa-floating-book{position:fixed;right:22px;bottom:22px;z-index:45;display:flex;align-items:center;gap:9px;padding:13px 17px;border-radius:999px;background:#ff9b52;color:#fff;font-weight:900;box-shadow:0 14px 32px rgba(255,155,82,.28);border:2px solid rgba(255,255,255,.9);transition:transform .2s ease,box-shadow .2s ease}.avtospa-floating-book:hover{transform:translateY(-4px);box-shadow:0 18px 38px rgba(255,155,82,.34)}.avtospa-floating-book .dot{width:9px;height:9px;border-radius:50%;background:#fff;box-shadow:0 0 0 6px rgba(255,255,255,.18);animation:avtospaPulse 1.8s infinite}.avtospa-nav-active{color:#229fd0!important}@keyframes avtospaPulse{0%,100%{transform:scale(1);opacity:1}50%{transform:scale(.72);opacity:.65}}@media(max-width:760px){.avtospa-floating-book{display:none}}@media(prefers-reduced-motion:reduce){.avtospa-reveal{opacity:1;transform:none;transition:none}.avtospa-floating-book .dot{animation:none}}';wp_add_inline_style('avtospa-style',$interactive_css);
 $wa=esc_url_raw(get_theme_mod('avtospa_whatsapp',''));$tg=esc_url_raw(get_theme_mod('avtospa_telegram',''));wp_add_inline_script('avtospa-navigation','document.addEventListener("DOMContentLoaded",function(){document.body.dataset.whatsapp='.wp_json_encode($wa).';document.body.dataset.telegram='.wp_json_encode($tg).';});','before');
 $interactive_js="document.addEventListener('DOMContentLoaded',function(){var bar=document.createElement('div');bar.className='avtospa-progress';bar.setAttribute('aria-hidden','true');document.body.appendChild(bar);var updateProgress=function(){var doc=document.documentElement;var max=doc.scrollHeight-window.innerHeight;bar.style.width=(max>0?(window.scrollY/max)*100:0)+'%';};window.addEventListener('scroll',updateProgress,{passive:true});updateProgress();var revealItems=document.querySelectorAll('.section,.tire-booking-banner,.hero-grid > div,.card,.benefit,.faq details,.contact-card,.autotech-banner-inner,.service-related-card,.service-page-hero');if('IntersectionObserver' in window){revealItems.forEach(function(el){el.classList.add('avtospa-reveal')});var observer=new IntersectionObserver(function(entries,obs){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('is-visible');obs.unobserve(entry.target)}})},{threshold:.12});revealItems.forEach(function(el){observer.observe(el)});}var sections=document.querySelectorAll('main section[id]');var navLinks=document.querySelectorAll('.main-nav a[href*=\"#\"]');if('IntersectionObserver' in window&&sections.length&&navLinks.length){var sectionObserver=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){navLinks.forEach(function(link){link.classList.remove('avtospa-nav-active');if(link.getAttribute('href').indexOf('#'+entry.target.id)>-1){link.classList.add('avtospa-nav-active')}})}})},{rootMargin:'-35% 0px -55% 0px',threshold:0});sections.forEach(function(section){sectionObserver.observe(section);});}});";wp_add_inline_script('avtospa-navigation',$interactive_js,'after');
} add_action('wp_enqueue_scripts','avtospa_assets');
function avtospa_floating_booking(){if(!is_front_page()){return;}echo '<a class="avtospa-floating-book" href="#tire-booking" aria-label="Записаться на шиномонтаж"><span class="dot" aria-hidden="true"></span>🛞 Записаться на шиномонтаж</a>';} add_action('wp_footer','avtospa_floating_booking',20);
function avtospa_customize_register($wp_customize){$wp_customize->add_section('avtospa_contacts',array('title'=>'АвтоСпа — контакты','priority'=>30));$wp_customize->add_setting('avtospa_phone',array('default'=>'+7 916 299-98-59','sanitize_callback'=>'sanitize_text_field'));$wp_customize->add_control('avtospa_phone',array('label'=>'Телефон','section'=>'avtospa_contacts','type'=>'text'));$wp_customize->add_setting('avtospa_address',array('default'=>'Россия, Москва, Полярный проезд, 18, стр. 2','sanitize_callback'=>'sanitize_text_field'));$wp_customize->add_control('avtospa_address',array('label'=>'Адрес','section'=>'avtospa_contacts','type'=>'text'));$wp_customize->add_setting('avtospa_whatsapp',array('default'=>'','sanitize_callback'=>'esc_url_raw'));$wp_customize->add_control('avtospa_whatsapp',array('label'=>'WhatsApp URL','section'=>'avtospa_contacts','type'=>'url'));$wp_customize->add_setting('avtospa_telegram',array('default'=>'','sanitize_callback'=>'esc_url_raw'));$wp_customize->add_control('avtospa_telegram',array('label'=>'Telegram URL','section'=>'avtospa_contacts','type'=>'url'));} add_action('customize_register','avtospa_customize_register');
function avtospa_phone_href(){return preg_replace('/[^0-9+]/','',(string)get_theme_mod('avtospa_phone','+7 916 299-98-59'));}
function avtospa_service_page_url($title,$fallback){$page=get_page_by_title($title,OBJECT,'page');return ($page&&$page->ID)?get_permalink($page->ID):home_url($fallback);}
function avtospa_fallback_menu(){$services=avtospa_service_page_url('Автомойка','/#services');$engine=avtospa_service_page_url('Мойка двигателя','/#engine-wash');$tire=avtospa_service_page_url('Шиномонтаж','/#tire-booking');echo '<ul><li><a href="'.esc_url($services).'">Услуги</a></li><li><a href="'.esc_url($engine).'">Мойка двигателя</a></li><li><a href="'.esc_url($tire).'">Шиномонтаж</a></li><li><a href="'.esc_url(home_url('/#contacts')).'">Контакты</a></li></ul>';}
function avtospa_has_seo_plugin(){return defined('WPSEO_VERSION')||defined('AIOSEO_VERSION')||defined('RANK_MATH_VERSION')||class_exists('RankMath');}
function avtospa_seo_description(){return 'АвтоСпа в Москве: автомойка, мойка двигателя и шиномонтаж. Полярный проезд, 18, стр. 2. Телефон для записи и уточнения условий.';}
function avtospa_service_seo(){if(avtospa_has_seo_plugin()||!is_page()){return;}$title=trim(wp_strip_all_tags(get_the_title()));$descriptions=array('Автомойка'=>'Автомойка АвтоСпа в Москве на Полярном проезде, 18, стр. 2. Уточните доступные варианты мойки и актуальные условия по телефону.','Мойка двигателя'=>'Мойка двигателя АвтоСпа в Москве на Полярном проезде, 18, стр. 2. Возможность выполнения услуги и условия уточняйте по телефону.','Шиномонтаж'=>'Шиномонтаж АвтоСпа в Москве на Полярном проезде, 18, стр. 2. Запись и актуальные условия по телефону.');if(isset($descriptions[$title])){echo '<meta name="description" content="'.esc_attr($descriptions[$title]).'">'.PHP_EOL;}}
add_action('wp_head','avtospa_service_seo',3);
function avtospa_document_title($title){if(avtospa_has_seo_plugin()){return $title;}if(is_404()){return 'Страница не найдена — АвтоСпа';}if(is_front_page()){return 'АвтоСпа — автомойка, мойка двигателя и шиномонтаж в Москве';}$service_titles=array('Автомойка','Мойка двигателя','Шиномонтаж');$current=trim(wp_strip_all_tags(get_the_title()));if(in_array($current,$service_titles,true)){return $current.' — АвтоСпа в Москве';}return $title;}
add_filter('pre_get_document_title','avtospa_document_title',20);
function avtospa_og_image(){if(is_front_page()){return get_template_directory_uri().'/assets/img/hero-auto.svg';}if(is_page()){ $title=trim(wp_strip_all_tags(get_the_title())); if(in_array($title,array('Автомойка','Мойка двигателя','Шиномонтаж'),true)){return get_template_directory_uri().'/assets/img/tire-service.svg';} return get_template_directory_uri().'/assets/img/hero-auto.svg';}return get_template_directory_uri().'/assets/img/hero-auto.svg';}
function avtospa_social_meta(){if(avtospa_has_seo_plugin()){return;}$image=avtospa_og_image();if(!$image){return;}$title=wp_get_document_title();$description=avtospa_seo_description();if(is_page()){$service=trim(wp_strip_all_tags(get_the_title()));$descriptions=array('Автомойка'=>'Автомойка АвтоСпа в Москве на Полярном проезде, 18, стр. 2. Уточните актуальные условия по телефону.','Мойка двигателя'=>'Мойка двигателя АвтоСпа в Москве на Полярном проезде, 18, стр. 2. Уточните возможность выполнения услуги и условия по телефону.','Шиномонтаж'=>'Шиномонтаж АвтоСпа в Москве на Полярном проезде, 18, стр. 2. Запись и актуальные условия по телефону.');if(isset($descriptions[$service])){$description=$descriptions[$service];}}echo '<meta property="og:title" content="'.esc_attr($title).'">';echo '<meta property="og:description" content="'.esc_attr($description).'">';echo '<meta property="og:type" content="'.(is_front_page()?'website':'article').'">';echo '<meta property="og:url" content="'.esc_url(get_permalink()).'">';echo '<meta property="og:image" content="'.esc_url($image).'">';echo '<meta property="og:site_name" content="АвтоСпа">';echo '<meta name="twitter:card" content="summary_large_image">';echo '<meta name="twitter:title" content="'.esc_attr($title).'">';echo '<meta name="twitter:description" content="'.esc_attr($description).'">';echo '<meta name="twitter:image" content="'.esc_url($image).'">';}
add_action('wp_head','avtospa_social_meta',8);
function avtospa_image_alt($attr,$attachment,$size){if(!empty($attr['alt'])){return $attr;}$title=trim(wp_strip_all_tags(get_the_title($attachment)));if(!$title){$title='Автомобильная услуга АвтоСпа';}$attr['alt']=$title.' — АвтоСпа, Москва';return $attr;}
add_filter('wp_get_attachment_image_attributes','avtospa_image_alt',10,3);



function avtospa_breadcrumb_schema(){if(avtospa_has_seo_plugin()||!is_page()){return;}$title=trim(wp_strip_all_tags(get_the_title()));$allowed=array('Автомойка','Мойка двигателя','Шиномонтаж');if(!in_array($title,$allowed,true)){return;}$data=array('@context'=>'https://schema.org','@type'=>'BreadcrumbList','itemListElement'=>array(array('@type'=>'ListItem','position'=>1,'name'=>'АвтоСпа','item'=>home_url('/')),array('@type'=>'ListItem','position'=>2,'name'=>$title,'item'=>get_permalink())));echo '<script type="application/ld+json">'.wp_json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).'</script>';}
add_action('wp_head','avtospa_breadcrumb_schema',26);
function avtospa_faq_schema(){if(avtospa_has_seo_plugin()||!is_front_page()){return;}$items=array(array('q'=>'Как записаться на шиномонтаж?','a'=>'Позвоните по номеру, указанному на сайте, и согласуйте удобное время.'),array('q'=>'Где находится АвтоСпа?','a'=>'Москва, Полярный проезд, 18, стр. 2. Карта и кнопка маршрута находятся в блоке «Отзывы и расположение».'),array('q'=>'Как посмотреть отзывы?','a'=>'Откройте карточку АвтоСпа в Яндекс Картах через блок отзывов на этой странице.'),array('q'=>'Как узнать актуальный перечень услуг?','a'=>'Позвоните нам — специалисты уточнят доступные услуги и условия.'));$main=array();foreach($items as $item){$main[]=array('@type'=>'Question','name'=>$item['q'],'acceptedAnswer'=>array('@type'=>'Answer','text'=>$item['a']));}$data=array('@context'=>'https://schema.org','@type'=>'FAQPage','mainEntity'=>$main);echo '<script type="application/ld+json">'.wp_json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).'</script>';}
add_action('wp_head','avtospa_faq_schema',27);



function avtospa_schema(){if(avtospa_has_seo_plugin()){return;}$phone=get_theme_mod('avtospa_phone','+7 916 299-98-59');$address=get_theme_mod('avtospa_address','Россия, Москва, Полярный проезд, 18, стр. 2');$url=home_url('/');$business_id=trailingslashit($url).'#business';$website_id=trailingslashit($url).'#website';$services=array('Автомойка','Мойка двигателя','Шиномонтаж');if(is_front_page()){$data=array('@context'=>'https://schema.org','@graph'=>array(array('@type'=>array('LocalBusiness','AutoWash'),'@id'=>$business_id,'name'=>'АвтоСпа','url'=>$url,'telephone'=>$phone,'description'=>avtospa_seo_description(),'serviceType'=>$services,'areaServed'=>array('@type'=>'City','name'=>'Москва'),'address'=>array('@type'=>'PostalAddress','streetAddress'=>$address,'addressLocality'=>'Москва','addressCountry'=>'RU'),'hasOfferCatalog'=>array('@type'=>'OfferCatalog','name'=>'Услуги АвтоСпа','itemListElement'=>array(array('@type'=>'Offer','itemOffered'=>array('@type'=>'Service','name'=>'Автомойка')),array('@type'=>'Offer','itemOffered'=>array('@type'=>'Service','name'=>'Мойка двигателя')),array('@type'=>'Offer','itemOffered'=>array('@type'=>'Service','name'=>'Шиномонтаж')))),'makesOffer'=>array_map(function($service){return array('@type'=>'Offer','itemOffered'=>array('@type'=>'Service','name'=>$service));},$services)),array('@type'=>'WebSite','@id'=>$website_id,'url'=>$url,'name'=>'АвтоСпа','inLanguage'=>'ru-RU','publisher'=>array('@id'=>$business_id))));$same_as=array();foreach(array('avtospa_whatsapp','avtospa_telegram') as $field){$social=get_theme_mod($field,'');if($social){$same_as[]=esc_url_raw($social);}}if($same_as){$data['@graph'][0]['sameAs']=$same_as;}echo '<script type="application/ld+json">'.wp_json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).'</script>'.PHP_EOL;return;}
 if(is_page()){$title=trim(wp_strip_all_tags(get_the_title()));$service_types=array('Автомойка','Мойка двигателя','Шиномонтаж');if(in_array($title,$service_types,true)){$service_url=get_permalink();$descriptions=array('Автомойка'=>'Автомойка АвтоСпа в Москве на Полярном проезде, 18, стр. 2.','Мойка двигателя'=>'Мойка двигателя АвтоСпа в Москве на Полярном проезде, 18, стр. 2.','Шиномонтаж'=>'Шиномонтаж АвтоСпа в Москве на Полярном проезде, 18, стр. 2.');$description=$descriptions[$title];$data=array('@context'=>'https://schema.org','@type'=>'Service','name'=>$title,'serviceType'=>$title,'url'=>$service_url,'description'=>$description,'provider'=>array('@id'=>$business_id,'@type'=>'LocalBusiness','name'=>'АвтоСпа','telephone'=>$phone,'address'=>array('@type'=>'PostalAddress','streetAddress'=>$address,'addressLocality'=>'Москва','addressCountry'=>'RU')),'areaServed'=>array('@type'=>'City','name'=>'Москва'));echo '<script type="application/ld+json">'.wp_json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).'</script>'.PHP_EOL;}}
}
add_action('wp_head','avtospa_schema',20);
function avtospa_service_template($template){if(!is_page()){return $template;}$title=trim(wp_strip_all_tags(get_the_title()));$service_titles=array('Автомойка','Мойка двигателя','Шиномонтаж');if(in_array($title,$service_titles,true)){ $candidate=get_template_directory().'/template-service.php'; if(file_exists($candidate)){return $candidate;}}return $template;}
add_filter('template_include','avtospa_service_template',99);
function avtospa_robots_txt($output,$public){if($public){$sitemap=home_url('/wp-sitemap.xml');$output="User-agent: *\nDisallow: /wp-admin/\nAllow: /wp-admin/admin-ajax.php\nSitemap: ".$sitemap."\n";}return $output;}
add_filter('robots_txt','avtospa_robots_txt',10,2);

/* Убираем только случайные буквальные \\n перед HTML страницы, которые иногда добавляют плагины/буфер вывода. */
function avtospa_clean_leading_output($html){
    return preg_replace('/^(?:\\s|\\\\n)+/u','',$html,1);
}
function avtospa_start_output_buffer(){
    if(!is_admin()&&!wp_doing_ajax()&&!defined('REST_REQUEST')){ob_start('avtospa_clean_leading_output');}
}
add_action('after_setup_theme','avtospa_start_output_buffer',99);
